static TMP_SRT: &str = "/home/caua/.cache/lrc-musica/tmp.srt";
static DIRETORIO_PADRAO: &str = "/home/caua/Sync";

fn openfiledialog_box() -> Option<PathBuf> {
    FileDialog::new()
        .set_directory_before(true)
        .build()
        .open_file()
}

/// Função principal da aplicação GTK.
/// Reorganiza os widgets de forma mais elegante e mantém a mesma lógica.
fn gtk_app(app: &Application) {
    // Grid centralizado com espaçamento confortável
    let grid = Grid::builder()
        .row_spacing(12)
        .column_spacing(12)
        .margin_top(24)
        .margin_start(24)
        .margin_end(24)
        .margin_bottom(24)
        .padding(8)
        .halign(gtk::Alignment::Center)
        .vexpand(true)
        .build();

    // Título informativo no topo do grid
    let title_label = Label::builder()
        .label("🎵 WhisperLRC — Gera legendas SRT a partir de áudio")
        .halign(gtk::Alignment::Center)
        .valign(gtk::Alignments::VerticalCenter)
        .build();
    grid.attach(&title_label, 0, 0, grid.n_columns(), 0);

    // Campo de entrada para o caminho do arquivo (ocupando 2 colunas)
    let entry = Entry::builder()
        .placeholder_text("Clique em ... para selecionar um arquivo de áudio...")
        .halign(gtk::Alignment::Start)
        .valign(gtk::Alignments::Top)
        .min_height(36)
        .build();

    // Botão de busca estilizado como ícone de pasta
    let search_button = Button::builder()
        .label("📂 Selecionar arquivo")
        .halign(gtk::Alignment::End)
        .valign(gtk::Alignments::Top)
        .build();

    // Conectar a abertura do diálogo ao botão de busca
    let entry_clone = entry.clone();
    search_button.connect_clicked(move |_| {
        if let Some(path) = openfiledialog_box() {
            if let Ok(text) = path.to_str() {
                entry.set_text(text);
            }
        }
    });

    // Caixa de texto adicional para colar manualmente o caminho
    let paste_entry = Entry::builder()
        .placeholder_text("Ou cole o caminho aqui")
        .halign(gtk::Alignment::Start)
        .valign(gtk::Alignments::Top)
        .min_height(36)
        .build();

    // Botão "Paste" alinhado à direita da caixa de colar
    let btn_paste = Button::builder()
        .label("📋 Colar")
        .halign(gtk::Alignment::End)
        .valign(gtk::Alignments::Top)
        .build();

    paste_entry.connect_signals(|controls, signal, _data| {
        match signal {
            gtk::widget::SignalConnectionId::ClipboardChanged(id) => {
                id.connect(move |connection, _| {
                    if connection.source().is_clipboard() {
                        if let Some(text) = controls[1].text() {
                            if !text.is_empty() {
                                entry.set_text(text);
                            }
                        }
                    }
                });
            }
            _ => {}
        }
    });

    // Caixa de combinação para escolher o modelo do Whisper
    let whisper_model_combo = ComboBoxText::new();
    whisper_model_combo.set_min_height(Some(40));
    whisper_model_combo.set_halign(gtk::Alignment::Start);
    whisper_model_combo.set_valign(gtk::Alignments::Top);

    let models = ["tiny", "tiny-quantized", "base", "small", "medium", "large", "turbo"];
    for model in &models {
        whisper_model_combo.append_text(model);
    }
    whisper_model_combo.set_active(Some(6)); // turbo já selecionado por padrão

    // CheckButton para ativar modo "2º plano" (background)
    let second_plane_check = CheckButton::with_label("⏳ Rodar em segundo plano?");
    second_plane_check.set_halign(gtk::Alignment::End);
    second_plane_check.set_valign(gtk::Alignments::Middle);

    // Label informativo sobre o arquivo atual
    let label_info = Rc::new(RefCell::new(Label::new(Some("ℹ️ Aguardando arquivo..." ))));
    label_info.set_halign(gtk::Alignment::Start);
    label_info.set_valign(gtk::Alignments::Bottom);

    // Conexão para atualizar o label quando o caminho muda
    let entry_clone = entry.clone();
    let paste_clone = paste_entry.clone();
    let label_info_clone = Rc::clone(&label_info);

    entry.connect_changed(move |_| {
        update_info(label_info_clone.borrow(), &entry_clone.text());
    });

    paste_entry.connect_changed(move |_| {
        update_info(label_info_clone.borrow(), &paste_clone.text());
    });

    fn update_info(label: &mut Label, text: &str) {
        if text.is_empty() {
            label.set_text(Some("ℹ️ Nenhum arquivo selecionado"));
        } else if text.starts_with("/") && text.contains(".") {
            // Verifica se parece um caminho válido
            if Path::new(text).exists() {
                label.set_text(Some(format!("🎯 Arquivo: {}", text)));
            } else {
                label.set_text(Some(format!("📁 Caminho informado: {}", text)));
            }
        } else {
            label.set_text(Some(format!("📄 Texto colado:\n{}", text.lines().join("\n"))));
        }
    }

    // Botões "Salvar Configuração" e "Executar" com ícones sutis
    let btn_save = Button::builder()
        .label("💾 Salvar Config")
        .halign(gtk::Alignment::Start)
        .valign(gtk::Alignments::Center)
        .min_height(40)
        .build();

    let btn_execute = Button::builder()
        .label("▶️ Gerar Legenda")
        .halign(gtk::Alignment::End)
        .valign(gtk::Alignments::Center)
        .min_height(40)
        .css_class("primary")
        .build();

    // Container horizontal para alinhar os botões
    let button_box = Box::new(Orientation::Horizontal, 16);
    button_box.set_halign(gtk::Alignment::Center);
    button_box.set_valign(gtk::Alignments::Middle);
    button_box.add(&btn_save);
    button_box.add(&btn_execute);

    // Adicionando tudo ao grid com alinhamento central
    grid.attach(&entry, 0, 1, 2, 1);
    grid.attach(&search_button, 2, 1, 1, 1);
    grid.attach(&paste_entry, 0, 2, 2, 1);
